class Solution {
public:
    string minWindow(string s, string t) {
        unordered_map<char, int> need, win;
        for (char ch : t) need[ch]++;
        int have = 0, want = need.size();
        int left = 0, bl = 0, br = -1, best = (int)s.size() + 1;
        for (int right = 0; right < (int)s.size(); right++) {
            char ch = s[right];
            if (need.count(ch)) {
                win[ch]++;
                if (win[ch] == need[ch]) have++;
            }
            while (have == want) {
                if (right - left + 1 < best) {
                    best = right - left + 1;
                    bl = left;
                    br = right;
                }
                char c = s[left];
                if (need.count(c)) {
                    win[c]--;
                    if (win[c] < need[c]) have--;
                }
                left++;
            }
        }
        return best <= (int)s.size() ? s.substr(bl, br - bl + 1) : "";
    }
};

